import{findEveProjectContext}from"#internal/project-context.js";function projectCommand(e,t){return e.hook(`preAction`,async()=>{let e=await findEveProjectContext(t.root);e?.kind===`standalone`&&(t.root=e.appRoot)})}function registerProjectCommands(e){projectCommand(e.program.command(`link`),e.applicationContext).description(`Link this directory to a Vercel project and pull AI Gateway credentials.`).option(`--non-interactive`,`Run without interactive prompts`).option(`--project <name-or-id>`,`Vercel project name or ID`).option(`--team <team-id-or-slug>`,`Vercel team ID or slug`).action(async t=>{let{runLinkCommand:n}=await import(`./link.js`);await n(e.logger,e.applicationContext.root,void 0,t)}),projectCommand(e.program.command(`deploy`),e.applicationContext).description(`Deploy the agent to Vercel production (links first if needed).`).option(`--non-interactive`,`Run without interactive prompts`).option(`--project <name-or-id>`,`Vercel project name or ID`).option(`--team <team-id-or-slug>`,`Vercel team ID or slug`).option(`-y, --yes`,`Confirm a non-interactive production deployment`).option(`--no-trace-sampling`,`Skip 100% Vercel trace sampling for a new project`).action(async t=>{let{runDeployCommand:n}=await import(`./deploy.js`);await n(e.logger,e.applicationContext.root,void 0,t)})}export{registerProjectCommands};